window.__votdWeek && window.__votdWeek({"week":"2027-12-13","reading":"Revelation 15–22","days":[{"d":"2027-12-13","ref":"Revelation 19:2","b":"Revelation","c":19,"v":2,"he":"כִּי־אֱמֶת וְיָשָׁר מִשְׁפָּטָיו כִּי־הֵשִׁיב גְּמוּל עַל־הַזּוֹנָה הַגְּדוֹלָה אֲשֶׁר־הִשְׁחִיתָה אֶת־הָאָרֶץ בְּתַזְנֻתָהּ לִדְרֹשׁ מִיָּדָהּ אֶת־דַּם־עֲבָדָיו׃","en":"For true and righteous are his judgments: for he hath judged the great whore, which did corrupt the earth with her fornication, and hath avenged the blood of his servants at her hand."},{"d":"2027-12-14","ref":"Revelation 19:15","b":"Revelation","c":19,"v":15,"he":"וּמִפִּיו יֹצֵאת חֶרֶב חַדָּה לְהַכּוֹת אֶת־הַגּוֹיִם וְהוּא יִרְעֵם בְּשֵׁבֶט בַּרְזֶל וְהוּא דֹרֵךְ פּוּרַת יֵין חֲמַת־אַף אֱלֹהֵי הַצְּבָאוֹת׃","en":"And out of his mouth goeth a sharp sword, that with it he should smite the nations: and he shall rule them with a rod of iron: and he treadeth the winepress of the fierceness and wrath of Almighty God."},{"d":"2027-12-15","ref":"Revelation 20:2","b":"Revelation","c":20,"v":2,"he":"וַיִּתְפֹּשׂ אֶת־הַתַּנִין אֶת־הַנָּחָשׁ הַקַּדְמוֹנִי הוּא הַמַּלְשִׁין וְהוּא הַשָּׂטָן וַיַּאַסְרֵהוּ אֶלֶף שָׁנִים׃","en":"And he laid hold on the dragon, that old serpent, which is the Devil, and Satan, and bound him a thousand years,"},{"d":"2027-12-16","ref":"Revelation 20:12","b":"Revelation","c":20,"v":12,"he":"וָאֵרֶא אֶת־הַמֵּתִים הַקְּטַנִּים עִם־הַגְּדֹלִים עֹמְדִים לִפְנֵי הַכִּסֵּא וּסְפָרִים נִפְתָּחִים וַיִּפָּתַח סֵפֶר אַחֵר וְהוּא סֵפֶר הַחַיִּים וַיִּשָּׁפְטוּ הַמֵּתִים מִן־הַכָּתוּב בַּסְּפָרִים כְּמַעֲשֵׂיהֶם׃","en":"And I saw the dead, small and great, stand before God; and the books were opened: and another book was opened, which is the book of life: and the dead were judged out of those things which were written in the books, according to their works."},{"d":"2027-12-17","ref":"Revelation 21:4","b":"Revelation","c":21,"v":4,"he":"וּמָחָה אֱלֹהִים כׇּל־דִּמְעָה מֵעֵינֵיהֶם וְהַמָּוֶת לֹא יִהְיֶה־עוֹד וְגַם־אֵבֶל וּזְעָקָה וּכְאֵב לֹא יִהְיֶה־עוֹד כִּי הָרִאשֹׁנוֹת עָבָרוּ׃","en":"And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away."},{"d":"2027-12-18","ref":"Revelation 21:8","b":"Revelation","c":21,"v":8,"he":"אֲבָל רַכֵּי הַלֵּב וַאֲשֶׁר אֵינָם מַאֲמִינִים וְהַמְגֹאָלִים וְהַמְרַצְּחִים וְהַזֹּנִים וְהַמְכַשְּׁפִים וְעֹבְדֵי הָאֱלִילִים וְכׇל־הַמְשַׁקְּרִים חֶלְקָם הָאֲגַם הַבֹּעֵר בְּאֵשׁ וְגׇפְרִית אֲשֶׁר־הוּא הַמָּוֶת הַשֵּׁנִי׃","en":"But the fearful, and unbelieving, and the abominable, and murderers, and whoremongers, and sorcerers, and idolaters, and all liars, shall have their part in the lake which burneth with fire and brimstone: which is the second death."},{"d":"2027-12-19","ref":"Revelation 22:12","b":"Revelation","c":22,"v":12,"he":"וְהִנְנִי בָא מַהֵר וּשְׂכָרִי אִתִּי לְשַׁלֵּם לְאִישׁ כְּמַעֲשֵׂהוּ׃","en":"And, behold, I come quickly; and my reward is with me, to give every man according as his work shall be."}]});
